{
  "items": [
    {
      "name": "Int.one_le_abs",
      "module_name": "Mathlib.Algebra.Order.Group.Unbundled.Int",
      "kind": "theorem",
      "type": "∀ {z : ℤ}, z ≠ 0 → 1 ≤ |z|"
    },
    {
      "name": "one_le_pow_mul_abs_eval_div",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : Field K] [inst_1 : LinearOrder K] [IsStrictOrderedRing K] {f : Polynomial ℤ} {a b : ℤ},\n  0 < b →\n    Polynomial.eval (↑a / ↑b) (Polynomial.map (algebraMap ℤ K) f) ≠ 0 →\n      1 ≤ ↑b ^ f.natDegree * |Polynomial.eval (↑a / ↑b) (Polynomial.map (algebraMap ℤ K) f)|"
    },
    {
      "name": "AbsoluteValue.ne_zero",
      "module_name": "Mathlib.Algebra.Order.AbsoluteValue.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_5} {S : Type u_6} [inst : Semiring R] [inst_1 : Semiring S] [inst_2 : PartialOrder S]\n  (abv : AbsoluteValue R S) {x : R}, x ≠ 0 → abv x ≠ 0"
    },
    {
      "name": "minpoly.aeval_ne_zero_of_dvdNotUnit_minpoly",
      "module_name": "Mathlib.FieldTheory.Minpoly.Basic",
      "kind": "theorem",
      "type": "∀ {A : Type u_1} {B : Type u_2} [inst : CommRing A] [inst_1 : Ring B] [inst_2 : Algebra A B] {x : B} {a : Polynomial A},\n  IsIntegral A x → a.Monic → DvdNotUnit a (minpoly A x) → (Polynomial.aeval x) a ≠ 0"
    },
    {
      "name": "Irreducible.aeval_ne_zero_of_natDegree_ne_one",
      "module_name": "Mathlib.Algebra.Polynomial.RingDivision",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : CommRing R] [IsDomain R] [inst_2 : Ring S] [inst_3 : Algebra R S] [FaithfulSMul R S]\n  {p : Polynomial R},\n  Irreducible p → p.natDegree ≠ 1 → ∀ {x : S}, x ∈ (algebraMap R S).range → (Polynomial.aeval x) p ≠ 0"
    },
    {
      "name": "Polynomial.tendsto_abv_aeval_atTop",
      "module_name": "Mathlib.Topology.Algebra.Polynomial",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_2} {k : Type u_3} {α : Type u_4} [inst : CommSemiring R] [inst_1 : Ring A]\n  [inst_2 : Algebra R A] [inst_3 : Field k] [inst_4 : LinearOrder k] [IsStrictOrderedRing k] (abv : A → k)\n  [IsAbsoluteValue abv] (p : Polynomial R),\n  0 < p.degree →\n    (algebraMap R A) p.leadingCoeff ≠ 0 →\n      ∀ {l : Filter α} {z : α → A},\n        Filter.Tendsto (abv ∘ z) l Filter.atTop →\n          Filter.Tendsto (fun x => abv ((Polynomial.aeval (z x)) p)) l Filter.atTop"
    },
    {
      "name": "Polynomial.one_le_mahlerMeasure_of_ne_zero",
      "module_name": "Mathlib.NumberTheory.MahlerMeasure",
      "kind": "theorem",
      "type": "∀ {p : Polynomial ℤ}, p ≠ 0 → 1 ≤ (Polynomial.map (Int.castRingHom ℂ) p).mahlerMeasure"
    },
    {
      "name": "Polynomial.isProperMap_eval",
      "module_name": "Mathlib.Topology.Algebra.Polynomial",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : NormedRing R] [IsAbsoluteValue norm] [ProperSpace R] (p : Polynomial R),\n  0 < p.degree → IsProperMap fun x => Polynomial.eval x p"
    }
  ]
}
